import fs from 'node:fs';import path from 'node:path';import {pathToFileURL} from 'node:url';import {chromium} from 'playwright-core';
const venues=process.argv.includes('--venues');
const root=path.resolve(venues?'.logs/venue-photos-20261107':'.logs/dishes-20261107'),r=JSON.parse(fs.readFileSync(venues?'docs/research/venue-candidates-20261107.json':'docs/research/dish-candidates-20261107.json','utf8'));
const entries=Object.values(r).flatMap(p=>(venues?p.photoCandidates??[]:p.candidates).map((c,i)=>({...c,id:p.id,index:i+1})));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1100}});for(let i=0;i<entries.length;i+=12){const file=path.join(root,`sheet-${i/12+1}.html`);fs.writeFileSync(file,`<meta charset=utf-8><style>body{font:13px system-ui;background:#eef3ef}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}figure{background:white;padding:8px;margin:0}img{width:100%;height:230px;object-fit:contain}figcaption{overflow-wrap:anywhere}</style><div class=grid>${entries.slice(i,i+12).map(p=>`<figure><img src="${pathToFileURL(path.join(root,p.file))}"><figcaption><b>${esc(p.id)} #${p.index}</b><br>${esc(p.source)}</figcaption></figure>`).join('')}</div>`);await page.goto(pathToFileURL(file).href);await page.waitForFunction(()=>[...document.images].every(i=>i.complete));await page.screenshot({path:path.join(root,`sheet-${i/12+1}.png`),fullPage:true});}}finally{await browser.close();}console.log(entries.length);
